const root=document.querySelector('#marketplace');
const iconize=html=>html.replaceAll('↗','<svg class="inline-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>').replaceAll('▶','<svg class="inline-icon play-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7Z"/></svg>');
const money=n=>'₦'+Number(n||0).toLocaleString('en-NG',{maximumFractionDigits:0});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
const state={products:[],categories:[],settings:{},saved:read('hsl_saved',[]),compare:read('hsl_compare',[]),cart:read('hamthel_cart_v1',[])};
const lockTypes=[{key:'fingerprint',name:'Fingerprint locks',words:/fingerprint/i,image:'2de4a97f81d186571e02.jpg'},{key:'pin',name:'PIN & keypad locks',words:/\bpin\b|keypad/i,image:'9a80b400e38a540ad405.jpg'},{key:'glass',name:'Glass door locks',words:/glass door|frameless glass/i,image:'6ba7eabe0d70c8e6fc49.jpg'},{key:'rim',name:'Rim & retrofit locks',words:/rim|retrofit/i,image:'7744d192af6d738dd501.jpg'},{key:'hotel',name:'Hotel & guest access',words:/hotel|rental|shortlet/i,image:'b9644299c2f0780c989a.jpg'},{key:'all',name:'All smart locks',words:/.*/,image:'9a80b400e38a540ad405.jpg'}];
const locks=()=>state.products.filter(p=>p.category==='smart-locks');
const text=p=>[p.name,p.short_description,p.description,...p.features||[]].join(' ');
const query=()=>new URLSearchParams(location.search);
const url=(changes={})=>{const q=query();for(const [k,v]of Object.entries(changes)){if(v===null||v==='')q.delete(k);else q.set(k,v)}return location.pathname+(q.size?'?'+q:'')};
const shop=(key,value)=>'/shop?'+new URLSearchParams({[key]:value});
const image=p=>p.images?.[0]||'/assets/9a80b400e38a540ad405.jpg';
const overview=p=>p.video_url||p.overview_video_url;
const isDiscount=p=>Number(p.compare_price)>Number(p.price);
const selected=()=>state.products.filter(p=>state.compare.includes(p.id));
function persist(){localStorage.setItem('hamthel_cart_v1',JSON.stringify(state.cart));localStorage.setItem('hsl_saved',JSON.stringify(state.saved));localStorage.setItem('hsl_compare',JSON.stringify(state.compare))}
function toast(message){document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.role='status';e.textContent=message;document.body.append(e);setTimeout(()=>e.remove(),2800)}
function logo(){return '<a class="logo" href="/" aria-label="Hamthel Smart Living home"><img src="/assets/6b7066e2cc2dcc59c828.png" alt="Hamthel Smart Living"></a>'}
function header(){return `<div class="offer">YOUR NEXT UPGRADE STARTS HERE. <strong>20% OFF DISCOUNTED PRODUCTS</strong> · Prices already reduced</div><header><div class="wrap"><div class="head">${logo()}<form class="search" action="/shop" role="search"><input name="q" aria-label="Search products" placeholder="Find your lock. Search by model, brand or feature…" value="${esc(query().get('q')||'')}"><button aria-label="Search">↗</button></form><div class="head-actions"><a class="hide-sm" href="/compare">Compare <span data-compare-count>(${state.compare.length})</span></a><a href="/saved" aria-label="Saved products">♡ <span data-saved-count>${state.saved.length}</span></a><button data-cart aria-label="Open cart">Bag <span data-cart-count>(${state.cart.reduce((n,p)=>n+p.quantity,0)})</span></button></div></div><nav class="nav" aria-label="Main navigation"><a class="all" href="/shop">☷ All categories</a><a href="/shop?category=smart-locks">Smart locks</a><a href="/shop?type=pin">PIN & keypad</a><a href="/shop?type=glass">Glass door locks</a><a href="/shop?category=smart-doors">Smart doors</a><a href="/videos">Watch & discover</a><a href="/compare">Compare locks</a><a href="/contact" class="right">Need a hand? Talk to an expert ↗</a></nav><nav class="page-nav" aria-label="About and support"><span>Smart living, one door at a time.</span><a href="/about">Our story</a><a href="/reviews">Customer stories</a><a href="/faq">FAQs</a><a href="/quiz">Lock finder</a><a href="/contact">Contact & installation</a></nav></div></header>`}
function footer(){const s=state.settings;return `<footer><div class="wrap"><div class="footer-grid"><div>${logo()}<p>One marketplace. A smarter way in. Discover smart locks and connected security for your home, office and next project.</p><a href="https://hamthelholdings.com" target="_blank" rel="noreferrer">A Hamthel Holdings company ↗</a></div><div><h3>Find your fit</h3><a href="/shop?category=smart-locks">All smart locks</a><a href="/shop?type=fingerprint">Fingerprint locks</a><a href="/shop?type=glass">Glass door locks</a><a href="/shop?category=smart-doors">Smart doors</a><a href="/compare">Compare products</a></div><div><h3>Good to know</h3><a href="/about">Our story</a><a href="/reviews">Customer stories</a><a href="/quiz">Lock finder</a><a href="/videos">Product videos</a><a href="/faq">Delivery & returns</a><a href="/contact">Installation & support</a><a href="/admin">Store administration</a></div><div><h3>Let's talk smart living</h3><a href="tel:${esc(s.phone)}">${esc(s.phone)}</a><a href="mailto:${esc(s.email)}">${esc(s.email)}</a><p>${esc(s.address)}<br>${esc(s.hours)}</p></div></div><div class="footer-base"><span>© ${new Date().getFullYear()} Hamthel Smart Living.</span><span>Prices in NGN · Orders confirmed before dispatch</span></div></div></footer><a class="support-float" href="https://wa.me/${esc(s.whatsapp||'2349160000066')}" target="_blank" rel="noreferrer">Talk smart living ↗</a><dialog id="video-dialog" aria-label="Product video"></dialog>`}
function price(p){return `<span class="price">${money(p.price)}${isDiscount(p)?`<del>${money(p.compare_price)}</del>`:''}</span>`}
function card(p){const saved=state.saved.includes(p.id);return `<article class="product"><a class="product-media" href="/product/${esc(p.slug)}" aria-label="View ${esc(p.name)}"><img src="${esc(image(p))}" alt="${esc(p.name)}" loading="lazy">${isDiscount(p)?'<span class="badge">20% OFF</span>':''}${overview(p)?'<span class="video-tag">▶ Product video</span>':''}</a><button class="save ${saved?'on':''}" data-save="${esc(p.id)}" aria-label="${saved?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved}">${saved?'♥':'♡'}</button><div class="product-body"><div class="meta"><span>${esc(p.brand)}</span><span class="stock">${p.stock_status==='Out of stock'?'Unavailable':'In stock'}</span></div><h3><a href="/product/${esc(p.slug)}">${esc(p.name)}</a></h3><p class="desc">${esc(p.short_description)}</p><div class="product-bottom">${price(p)}<button class="add" data-add="${esc(p.id)}" aria-label="Add ${esc(p.name)} to bag" ${p.stock_status==='Out of stock'?'disabled':''}>+</button></div><label class="compare-control"><input type="checkbox" data-compare="${esc(p.id)}" ${state.compare.includes(p.id)?'checked':''}> Add to comparison</label></div></article>`}
function videoCard(p){return `<button class="video-card" data-video="${esc(p.id)}" aria-label="Watch ${esc(p.name)}"><img src="${esc(image(p))}" alt="${esc(p.name)}" loading="lazy"><span class="play">▶</span><span class="caption"><strong>${esc(p.name)}</strong><small>${p.video_url?'Product video':'Product overview · catalogue images'} ↗</small></span></button>`}
function categoryTiles(){return lockTypes.map(t=>{const count=locks().filter(p=>t.words.test(text(p))).length;return `<a class="category-tile" href="${t.key==='all'?'/shop?category=smart-locks':shop('type',t.key)}"><img src="/assets/${t.image}" alt="" loading="lazy"><strong>${t.name}</strong><small>${count} ${count===1?'product':'products'} ↗</small></a>`}).join('')}
function home(){const featured=locks().filter(p=>p.stock_status!=='Out of stock').slice(0,8);return `<main><div class="wrap"><section class="hero"><div class="hero-copy"><div class="eyebrow">A smarter way in</div><h1>Your door.<br>Your rules.<br><em>Your perfect lock.</em></h1><p>Discover a world of keyless possibilities. Shop smart locks by brand, door type and the way you live — all in one place.</p><div class="actions"><a class="btn" href="/shop?category=smart-locks">Explore smart locks <span>↗</span></a><a class="text-link" href="/videos">▶ See them up close</a></div></div><div class="hero-visual"><img src="/assets/79617c144c180d5b6975.jpg" alt="Smart security for the modern home" fetchpriority="high"><span class="pill">20% off discounted picks ↗</span><div class="hero-caption"><span>THE KEYLESS COLLECTION</span><h3>Goodbye keys.<br>Hello possibilities.</h3><a href="/shop?type=fingerprint">Meet fingerprint entry ↗</a></div></div></section><div class="service-strip"><div><span class="service-icon">↗</span><span><b>Nationwide delivery</b><small>Free on orders from ${money(state.settings.free_shipping_threshold||250000)}</small></span></div><div><span class="service-icon">◇</span><span><b>Installation support</b><small>Available in Lagos & Abuja</small></span></div><div><span class="service-icon">⊞</span><span><b>Find the right fit</b><small>Compare brands and specifications</small></span></div><div><span class="service-icon">☏</span><span><b>People, not guesswork</b><small>Get help choosing your lock</small></span></div></div><section class="section"><div class="section-top"><div><div class="eyebrow">Find your kind of smart</div><h2>Every door has a match.</h2></div><a class="text-link" href="/shop">All categories ↗</a></div><div class="category-grid">${categoryTiles()}</div></section><section class="section" style="padding-top:15px"><div class="section-top"><div><div class="eyebrow">The smart-lock edit</div><h2>Less searching. More unlocking.</h2><p>Explore the collection. Compare your favourites. Make it yours.</p></div><a class="text-link" href="/shop?category=smart-locks">Shop the collection ↗</a></div><div class="tabs" style="margin-bottom:25px"><a class="active" href="/shop?category=smart-locks">All smart locks</a><a href="/shop?type=fingerprint">Fingerprint</a><a href="/shop?type=pin">PIN & keypad</a><a href="/shop?type=glass">Glass doors</a><a href="/shop?type=hotel">Guest access</a></div><div class="grid">${featured.map(card).join('')}</div></section><section class="section"><div class="editorial"><img src="/assets/bac0d904b7c7541a3274.jpg" alt="A modern entrance with smart access" loading="lazy"><div class="editorial-copy"><div class="eyebrow">Designed around your everyday</div><h2>Not just a lock.<br>A better way home.</h2><p>Fingerprint, PIN, card or app. Choose the access that works for your door, your household and your routine. We’ll help with the details.</p><div class="actions"><a class="btn light" href="/shop?type=fingerprint">Find your fit ↗</a><a class="text-link" href="/contact">Ask an expert</a></div></div></div></section><section class="section"><div class="section-top"><div><div class="eyebrow">Watch before you choose</div><h2>A closer look at your next lock.</h2><p>Product overviews made from catalogue images. Explore the details at your own pace.</p></div><a class="text-link" href="/videos">Video library ↗</a></div><div class="video-grid">${featured.slice(0,4).map(videoCard).join('')}</div></section><section class="section"><div class="section-top"><div><div class="eyebrow">Brands, together</div><h2>Your favourites. One destination.</h2></div></div><div class="brand-list">${[...new Set(locks().map(p=>p.brand))].slice(0,8).map(b=>`<a href="${shop('brand',b)}">${esc(b)}</a>`).join('')}</div></section><div class="newsletter"><div><div class="eyebrow">Stay in the know</div><h2>A smarter inbox starts here.</h2><p>New products, collection updates and helpful guides.</p></div><form id="newsletter"><input type="email" name="email" required placeholder="Your email address" aria-label="Email address"><button class="btn">Join us ↗</button></form></div></div></main>`}
function filtered(){const q=query();let items=q.get('type')?locks():state.products;const type=lockTypes.find(t=>t.key===q.get('type'));if(type)items=items.filter(p=>type.words.test(text(p)));if(q.get('category'))items=items.filter(p=>p.category===q.get('category'));if(q.get('brand'))items=items.filter(p=>p.brand===q.get('brand'));if(q.get('q')){const words=q.get('q').toLowerCase().split(/\s+/);items=items.filter(p=>words.every(w=>text(p).toLowerCase().includes(w)))}if(q.get('budget'))items=items.filter(p=>p.price<=Number(q.get('budget')));if(q.get('stock'))items=items.filter(p=>p.stock_status!=='Out of stock');if(q.get('deals'))items=items.filter(isDiscount);if(q.get('sort')==='price-up')items=items.toSorted((a,b)=>a.price-b.price);if(q.get('sort')==='price-down')items=items.toSorted((a,b)=>b.price-a.price);if(q.get('sort')==='name')items=items.toSorted((a,b)=>a.name.localeCompare(b.name));return items}
function filterPanel(){const q=query();return `<details class="filters" ${innerWidth>700?'open':''}><summary>Filter & refine</summary><div class="filters-inner"><div class="filter-group filter-links"><h3>Shop by category</h3><a class="${!q.get('category')?'active':''}" href="/shop">All products</a>${state.categories.map(c=>`<a class="${q.get('category')===c.slug?'active':''}" href="${shop('category',c.slug)}">${esc(c.name)}</a>`).join('')}</div><div class="filter-group filter-links"><h3>Your lock type</h3>${lockTypes.filter(t=>t.key!=='all').map(t=>`<a class="${q.get('type')===t.key?'active':''}" href="${shop('type',t.key)}">${t.name}</a>`).join('')}</div><div class="filter-group"><h3>Brand</h3><select aria-label="Filter by brand" data-filter="brand"><option value="">All brands</option>${[...new Set(state.products.map(p=>p.brand))].sort().map(b=>`<option ${q.get('brand')===b?'selected':''}>${esc(b)}</option>`).join('')}</select></div><div class="filter-group"><h3>Budget</h3><select aria-label="Maximum price" data-filter="budget"><option value="">Any price</option>${[250000,500000,750000,1000000].map(v=>`<option value="${v}" ${q.get('budget')===String(v)?'selected':''}>Up to ${money(v)}</option>`).join('')}</select><label><input type="checkbox" data-filter="stock" ${q.has('stock')?'checked':''}> In stock only</label><label><input type="checkbox" data-filter="deals" ${q.has('deals')?'checked':''}> 20% off offers</label><a class="text-link" href="/shop">Reset all filters</a></div></div></details>`}
function browse(){const q=query(),items=filtered(),page=Math.max(1,Math.min(Number(q.get('page'))||1,Math.ceil(items.length/18)||1)),pages=Math.ceil(items.length/18);const title=q.get('q')?'Results for “'+q.get('q')+'”':lockTypes.find(t=>t.key===q.get('type'))?.name||q.get('brand')||state.categories.find(c=>c.slug===q.get('category'))?.name||'Discover your next upgrade.';return `<main class="wrap"><div class="page-heading"><div class="eyebrow">The marketplace</div><h1>${esc(title)}</h1><p>Different doors. Different needs. Find the right smart lock and connected essentials for yours.</p></div><div class="browse">${filterPanel()}<div><div class="results-bar"><span>${items.length} products${items.length?' · '+((page-1)*18+1)+'–'+Math.min(page*18,items.length):''}</span><select aria-label="Sort products" data-filter="sort"><option value="">Sort: recommended</option><option value="price-up" ${q.get('sort')==='price-up'?'selected':''}>Price: low to high</option><option value="price-down" ${q.get('sort')==='price-down'?'selected':''}>Price: high to low</option><option value="name" ${q.get('sort')==='name'?'selected':''}>Name: A–Z</option></select></div>${items.length?`<div class="grid">${items.slice((page-1)*18,page*18).map(card).join('')}</div>`:empty('No matches just yet.','Try a different brand, feature or budget.')}<div class="pagination">${Array.from({length:pages},(_,i)=>`<a aria-label="Page ${i+1}" ${page===i+1?'aria-current="page"':''} class="${page===i+1?'active':''}" href="${esc(url({page:i+1}))}">${i+1}</a>`).join('')}</div></div></div></main>`}
function empty(title,description){return `<div class="empty"><h2>${title}</h2><p>${description}</p><a class="btn" href="/shop?category=smart-locks">Explore smart locks ↗</a></div>`}
function embedVideo(p){const source=overview(p)||'';const youtube=source.match(/(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([\w-]{6,})/i),vimeo=source.match(/vimeo\.com\/(\d+)/i);return youtube||vimeo?`<iframe src="${youtube?'https://www.youtube.com/embed/'+youtube[1]:'https://player.vimeo.com/video/'+vimeo[1]}" title="${esc(p.name)} video" allowfullscreen></iframe>`:`<video controls playsinline preload="none" poster="${esc(image(p))}" src="${esc(source)}" aria-label="${esc(p.name)} product overview"></video>`}
function product(){const p=state.products.find(p=>p.slug===decodeURIComponent(location.pathname.split('/').pop()));if(!p)return `<main class="wrap section">${empty('Product not found.','This product may no longer be available.')}</main>`;document.title=p.name+' | Hamthel Smart Living';const related=state.products.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4);return `<main class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / <a href="/shop?category=${esc(p.category)}">${esc(state.categories.find(c=>c.slug===p.category)?.name||'Shop')}</a> / ${esc(p.name)}</div><section class="product-detail"><div><div class="gallery-main"><img id="main-image" src="${esc(image(p))}" alt="${esc(p.name)}">${isDiscount(p)?'<span class="badge">20% OFF</span>':''}</div><div class="gallery-thumbs">${(p.images||[]).map((src,i)=>`<button data-image="${esc(src)}" aria-label="View image ${i+1} of ${esc(p.name)}"><img src="${esc(src)}" alt=""></button>`).join('')}${overview(p)?`<button data-video="${esc(p.id)}" aria-label="Watch product video">▶<br><small>Video</small></button>`:''}</div></div><div class="detail-copy"><div class="eyebrow">${esc(p.brand)} collection</div><h1>${esc(p.name)}</h1><p class="intro">${esc(p.short_description)}</p>${price(p)}${isDiscount(p)?`<p class="savings">Save ${money(p.compare_price-p.price)} · 20% off the list price</p>`:''}<div class="detail-features">${(p.features||[]).slice(0,3).map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="small-note">${p.stock_status==='Out of stock'?'Currently out of stock':'● In stock'} · Order confirmed before dispatch</p><div class="buy-row"><div class="qty"><button data-qty="-1" aria-label="Decrease quantity">−</button><input id="quantity" type="number" value="1" min="1" max="99" aria-label="Quantity"><button data-qty="1" aria-label="Increase quantity">+</button></div><button class="btn" data-add="${esc(p.id)}" ${p.stock_status==='Out of stock'?'disabled':''}>Add to bag +</button></div><div class="actions" style="margin-top:18px"><button class="text-link" data-save="${esc(p.id)}">${state.saved.includes(p.id)?'♥ Saved':'♡ Save for later'}</button><label class="compare-control" style="margin:0;border:0;padding:0"><input type="checkbox" data-compare="${esc(p.id)}" ${state.compare.includes(p.id)?'checked':''}> Compare this lock</label></div><div class="detail-note">Free delivery on orders from ${money(state.settings.free_shipping_threshold||250000)}.<br>Installation support in Lagos & Abuja. Contact us to check door compatibility before ordering.</div><a class="text-link" style="display:inline-block;margin-top:20px" href="https://wa.me/${esc(state.settings.whatsapp)}?text=${encodeURIComponent('Hello Hamthel, I would like advice about '+p.name)}" target="_blank" rel="noreferrer">Ask about this product ↗</a></div></section>${overview(p)?`<section class="detail-section"><div class="product-video"><div><div class="eyebrow">See it up close</div><h2>Meet the ${esc(p.name)}.</h2><p>Take a closer look before you choose. Explore the product images, then check the specifications below for your door.</p><p class="note">${p.video_url?'Product video.':'This product overview is created from catalogue imagery. It is not a demonstration of the lock in operation.'}</p></div>${embedVideo(p)}</div></section>`:''}<section class="detail-section"><div class="detail-cols"><div><h2>The details</h2><p>${esc(p.description)}</p></div><div><h2>What it offers</h2><ul>${(p.features||[]).map(f=>`<li>${esc(f)}</li>`).join('')}</ul></div></div></section><section class="detail-section"><h2>Know the specifications.</h2><div class="specs">${(p.specs||[]).map(s=>`<div class="spec-row"><span>${esc(s.label)}</span><strong>${esc(s.value)}</strong></div>`).join('')}</div><p class="small-note" style="margin-top:18px">Confirm door measurements and installation requirements with our team before purchase.</p></section><section class="section"><div class="section-top"><div><div class="eyebrow">Keep exploring</div><h2>More ways to make an entrance.</h2></div><a class="text-link" href="/shop?category=${esc(p.category)}">View collection ↗</a></div><div class="grid">${related.map(card).join('')}</div></section></main>`}
function saved(){const ps=state.products.filter(p=>state.saved.includes(p.id));return `<main class="wrap section"><div class="section-top"><div><div class="eyebrow">Your shortlist</div><h2>Worth coming back to.</h2><p>Saved on this browser, ready when you are.</p></div></div>${ps.length?`<div class="grid">${ps.map(card).join('')}</div>`:empty('Your shortlist starts here.','Tap the heart on any product to save it for later.')}</main>`}
function compare(){const ps=selected();const rows=[['Price',p=>price(p)],['Brand',p=>esc(p.brand)],['Availability',p=>esc(p.stock_status)],['Features',p=>(p.features||[]).map(esc).join('<br><br>')],...Array.from(new Set(ps.flatMap(p=>(p.specs||[]).map(s=>s.label)))).map(label=>[label,p=>esc(p.specs?.find(s=>s.label===label)?.value||'Not listed')])];return `<main class="wrap section"><div class="section-top"><div><div class="eyebrow">Side by side</div><h2>Choose with a little more clarity.</h2><p>Compare up to three products. Specifications come from the current catalogue.</p></div><a class="text-link" href="/shop?category=smart-locks">Add products ↗</a></div>${ps.length?`<div class="compare-table"><table><thead><tr><th>Compare products</th>${ps.map(p=>`<td><img src="${esc(image(p))}" alt="${esc(p.name)}"><a href="/product/${esc(p.slug)}"><strong>${esc(p.name)}</strong></a><br><button class="text-link" data-remove-compare="${esc(p.id)}" style="margin-top:15px">Remove</button></td>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th scope="row">${esc(label)}</th>${ps.map(p=>`<td>${fn(p)}</td>`).join('')}</tr>`).join('')}<tr><th>Explore</th>${ps.map(p=>`<td><a class="btn" href="/product/${esc(p.slug)}">View product ↗</a></td>`).join('')}</tr></tbody></table></div>`:empty('Make room for your favourites.','Choose “Add to comparison” on up to three products.')}</main>`}
function videos(){const q=query(),all=locks().filter(p=>overview(p)&&(!q.get('q')||text(p).toLowerCase().includes(q.get('q').toLowerCase()))),page=Math.max(1,Math.min(Number(q.get('page'))||1,Math.ceil(all.length/16)||1));return `<main class="wrap video-library section"><div class="section-top"><div><div class="eyebrow">The video library</div><h2>Smart locks, in the spotlight.</h2><p>Browse product overviews for every smart lock. Catalogue-image showcases, clearly labelled.</p></div></div><form class="search" action="/videos" style="max-width:500px;margin:0 0 30px"><input name="q" placeholder="Search lock videos…" aria-label="Search lock videos" value="${esc(q.get('q')||'')}"><button aria-label="Search videos">↗</button></form><p class="small-note" style="margin-bottom:20px">${all.length} product videos · For operating or installation demonstrations, ask our team.</p>${all.length?`<div class="video-grid">${all.slice((page-1)*16,page*16).map(videoCard).join('')}</div>`:empty('No videos match your search.','Try a model name or brand.')}<div class="pagination">${Array.from({length:Math.ceil(all.length/16)},(_,i)=>`<a class="${page===i+1?'active':''}" href="${esc(url({page:i+1}))}">${i+1}</a>`).join('')}</div></main>`}
function checkout(){const order=state.lastOrder;if(order)return `<main class="wrap section" style="max-width:850px"><div class="eyebrow">Your next upgrade</div><div class="page-heading"><h1>Order received.</h1><p>Your reference is <strong>${esc(order.order_number)}</strong>. Our team will contact you on ${esc(order.phone)} to confirm stock, delivery and payment arrangements.</p></div><div class="detail-section"><h2>Order acknowledgement</h2>${order.items.map(p=>`<div class="spec-row"><span>${p.quantity} × ${esc(p.name)}</span><strong>${money(p.price*p.quantity)}</strong></div>`).join('')}<div class="spec-row"><span>Delivery</span><strong>${order.shipping_fee?money(order.shipping_fee):'Free'}</strong></div><div class="spec-row"><span>Total</span><strong>${money(order.total)}</strong></div><p class="small-note" style="margin-top:20px">No payment has been collected online. Payment method: ${esc(order.payment_method)}. Keep your order reference for support.</p><div class="actions"><button class="btn" data-download-order>Download summary ↓</button><a class="btn outline" href="/shop">Keep exploring</a></div></div></main>`;if(!state.cart.length)return `<main class="wrap section">${empty('Your bag is waiting.','Add a product to start your order.')}</main>`;const subtotal=state.cart.reduce((n,p)=>n+p.price*p.quantity,0),shipping=subtotal>=(state.settings.free_shipping_threshold??250000)?0:(state.settings.shipping_fee??15000);return `<main class="wrap"><div class="breadcrumbs"><a href="/shop">Marketplace</a> / <button data-cart>Shopping bag</button> / Checkout</div><div class="page-heading"><div class="eyebrow">One step closer</div><h1>Make it yours.</h1><p>Tell us where your upgrade is going. We confirm every order before dispatch. No payment is collected online.</p></div><div class="checkout-layout"><form id="checkout-form"><h2>Delivery details</h2><div class="checkout-fields"><label>Full name *<input name="customer_name" required autocomplete="name" maxlength="120"></label><label>Phone / WhatsApp *<input name="phone" type="tel" required autocomplete="tel" pattern="[+0-9 ()-]{7,24}" maxlength="24"></label><label>Email (optional)<input name="email" type="email" autocomplete="email" maxlength="200"></label><label>City *<input name="city" required autocomplete="address-level2" maxlength="120"></label><label class="wide">Delivery address *<input name="address" required autocomplete="street-address" maxlength="400"></label><label>State *<select name="state" required><option value="">Choose your state</option>${['Abia','Abuja','Adamawa','Akwa Ibom','Anambra','Bauchi','Bayelsa','Benue','Borno','Cross River','Delta','Ebonyi','Edo','Ekiti','Enugu','Gombe','Imo','Jigawa','Kaduna','Kano','Katsina','Kebbi','Kogi','Kwara','Lagos','Nasarawa','Niger','Ogun','Ondo','Osun','Oyo','Plateau','Rivers','Sokoto','Taraba','Yobe','Zamfara'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>Delivery note (optional)<input name="notes" maxlength="600" placeholder="Gate, estate or access information"></label></div><h2 style="margin:30px 0 18px">Payment arrangement</h2><label class="payment-choice"><input type="radio" name="payment_method" value="Bank transfer" checked><span><strong>Bank transfer</strong><small>We share account details after confirming stock.</small></span></label><label class="payment-choice"><input type="radio" name="payment_method" value="Pay on delivery"><span><strong>Pay on delivery</strong><small>Available in Lagos and Abuja, subject to confirmation.</small></span></label><p id="checkout-error" role="alert" class="error" hidden></p><button class="btn" type="submit" style="width:100%;margin-top:25px">Place order ↗</button><p class="small-note" style="margin-top:14px">We use your delivery details to process and follow up on this order.</p></form><aside class="checkout-summary"><h2>Your upgrade, summarised.</h2>${state.cart.map(p=>`<div class="cart-item"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><p class="small-note">Qty ${p.quantity}</p><span class="price">${money(p.price*p.quantity)}</span></div></div>`).join('')}<div class="spec-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="spec-row"><span>Delivery</span><strong>${shipping?money(shipping):'Free'}</strong></div><div class="spec-row"><span>Total</span><strong>${money(subtotal+shipping)}</strong></div><p class="small-note" style="margin-top:20px">${esc(state.settings.shipping_note||'Delivery and installation arrangements are confirmed by our team.')}</p><button class="text-link" style="margin-top:20px" data-cart>Edit shopping bag</button></aside></div></main>`}

function infoHeading(eyebrow,title,description){return `<div class="page-heading info-heading"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>`}
function aboutPage(){const s=state.settings;document.title='Our story | Hamthel Smart Living';return `<main class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / Our story</div><section class="info-hero"><div><div class="eyebrow">Hamthel Smart Living</div><h1>${esc(s.about_heading||'A smarter way to come home.')}</h1><p>Smart security. Helpful advice. A Hamthel Holdings company.</p><a class="btn" href="/shop?category=smart-locks">Explore the collection ↗</a></div><img src="${esc(s.about_image||'/assets/d87e19b63e0d8ac61f47.png')}" alt="Hamthel Smart Living" fetchpriority="high"></section><section class="section story-grid"><div><div class="eyebrow">Our story</div><h2>One door.<br>A world of possibilities.</h2></div><div><p>${esc(s.about_body||'Hamthel Smart Living is the smart-home and security arm of Hamthel Holdings.')}</p><p>Explore smart locks, doors, doorbells, cameras and safes in one marketplace. Compare the details, shortlist your favourites and speak to our team about the right fit.</p><a class="text-link" href="/contact">Meet your next upgrade with a little help ↗</a></div></section><section class="section"><div class="section-top"><div><div class="eyebrow">Built around your choice</div><h2>A clearer path to smart living.</h2></div></div><div class="values-grid"><article><span>01 / DISCOVER</span><h3>Start with your door.</h3><p>Browse by lock type, feature and brand. The lock finder helps narrow the catalogue around your priorities and budget.</p><a href="/quiz" class="text-link">Find my lock ↗</a></article><article><span>02 / COMPARE</span><h3>The details matter.</h3><p>View specifications and product imagery, watch a catalogue overview, and compare up to three products side by side.</p><a href="/compare" class="text-link">Compare products ↗</a></article><article><span>03 / ASK</span><h3>Bring your questions.</h3><p>Share door measurements and photos with the team before ordering. Installation support is available in Lagos and Abuja.</p><a href="/contact" class="text-link">Talk to the team ↗</a></article></div></section><section class="section"><div class="info-cta"><div><div class="eyebrow">Your next chapter starts at the door</div><h2>Make room for a smarter entrance.</h2><p>From the first question to choosing the right product.</p></div><a href="/shop" class="btn">Discover the marketplace ↗</a></div></section></main>`}
function contactPage(){const s=state.settings;document.title='Contact & installation | Hamthel Smart Living';return `<main class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / Contact & installation</div>${infoHeading('Advice before the sale','Let’s find the right fit.','A question about your door, a product or an installation? Tell us what you have in mind.')}<section class="contact-layout"><aside><div class="contact-card"><div class="eyebrow">Talk smart living</div><h2>Real questions.<br>Helpful people.</h2><a class="contact-channel" href="https://wa.me/${esc(s.whatsapp)}" target="_blank" rel="noreferrer"><small>WHATSAPP</small><strong>Chat with a specialist ↗</strong></a><a class="contact-channel" href="tel:${esc(s.phone)}"><small>CALL US</small><strong>${esc(s.phone)}</strong></a><a class="contact-channel" href="mailto:${esc(s.email)}"><small>EMAIL</small><strong>${esc(s.email)}</strong></a><div class="contact-channel"><small>VISIT & OPENING HOURS</small><p>${esc(s.address)}<br>${esc(s.hours)}</p></div></div><div class="installation-note"><h3>Planning an installation?</h3><p>For a useful first conversation, have your door type, thickness and a clear photo ready. Send photos directly to the team on WhatsApp.</p><p>${esc(s.shipping_note||'Ask our team about delivery and installation options.')}</p></div></aside><div><form id="contact-form" class="contact-form"><h2>Tell us about your project.</h2><p class="small-note">Your enquiry goes to the Hamthel team. Include an email or phone number so they can reply.</p><div class="checkout-fields"><label>Your name *<input name="name" required maxlength="120" autocomplete="name"></label><label>Phone / WhatsApp<input name="phone" type="tel" maxlength="24" autocomplete="tel"></label><label class="wide">Email address<input name="email" type="email" maxlength="200" autocomplete="email"></label><label class="wide">What can we help with?<select name="interest"><option>Choosing a smart lock</option><option>Installation advice</option><option>Smart doors</option><option>Cameras & doorbells</option><option>Order support</option><option>Estate or business project</option><option>Something else</option></select></label><label class="wide">Your message *<textarea name="message" required rows="6" maxlength="5000" placeholder="Tell us about the door, the products you’re considering or your order reference."></textarea></label></div><p id="contact-feedback" role="status" class="form-feedback" hidden></p><button type="submit" class="btn" style="margin-top:24px">Send enquiry ↗</button><p class="small-note" style="margin-top:16px">Use WhatsApp or call the team for time-sensitive enquiries.</p></form><div id="contact-success" class="contact-success" hidden tabindex="-1"><div class="eyebrow">Enquiry received</div><h2>Thanks for getting in touch.</h2><p>Your message has been saved for the Hamthel team. They’ll use the contact details you provided to follow up.</p><button class="btn" data-contact-again>Send another enquiry</button><a class="text-link" href="/shop">Keep exploring ↗</a></div></div></section><section class="section"><div class="info-cta"><div><h2>Need a starting point?</h2><p>Try the lock finder or compare your favourite products.</p></div><a href="/quiz" class="btn">Find my lock ↗</a></div></section></main>`}
function faqPage(){document.title='FAQs, delivery & returns | Hamthel Smart Living';return `<main class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / Frequently asked questions</div>${infoHeading('A little clarity','Good questions. Clear answers.','Explore the store’s guidance on smart locks, delivery, installation, warranty and returns.')}<section class="faq-layout"><aside><form class="search faq-search" role="search" onsubmit="return false"><input id="faq-search" aria-label="Search frequently asked questions" placeholder="Search questions…"><span aria-hidden="true">⌕</span></form><p class="small-note" style="margin:15px 0" id="faq-count" aria-live="polite">${state.faqs.length} questions</p><div class="faq-help"><h3>Something more specific?</h3><p>Door measurements and installation requirements vary. Our team can help with your situation.</p><a href="/contact" class="btn">Ask the team ↗</a></div></aside><div id="faq-list">${state.faqs.length?state.faqs.map((f,i)=>`<details class="faq-item" data-faq-text="${esc((f.question+' '+f.answer).toLowerCase())}"><summary><span class="faq-index">${String(i+1).padStart(2,'0')}</span><span>${esc(f.question)}</span><span class="faq-toggle" aria-hidden="true">+</span></summary><div class="faq-answer"><p>${esc(f.answer)}</p></div></details>`).join(''):'<div class="empty"><h2>Have a question?</h2><p>Contact the team for the latest product and delivery guidance.</p><a class="btn" href="/contact">Get in touch</a></div>'}<div id="faq-empty" class="empty" hidden><h2>No matching questions.</h2><p>Try a different word or contact the team.</p><a class="text-link" href="/contact">Ask a question ↗</a></div></div></section><section class="section"><div class="info-cta"><div><div class="eyebrow">Ready to explore?</div><h2>Your door’s next chapter.</h2><p>Find products, compare specifications and choose with confidence.</p></div><a class="btn" href="/shop">Browse the marketplace ↗</a></div></section></main>`}
function reviewsPage(){document.title='Customer stories | Hamthel Smart Living';const reviews=state.reviews,average=reviews.length?reviews.reduce((n,r)=>n+Number(r.rating||0),0)/reviews.length:0;return `<main class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / Customer stories</div><section class="reviews-intro">${infoHeading('From the Hamthel community','Smart living, in their words.','Read the customer stories published by the Hamthel store.')}<div class="reviews-score"><span class="review-stars" aria-label="${average.toFixed(1)} out of 5 stars">★★★★★</span><strong>${average?average.toFixed(1):'—'}<small> / 5</small></strong><p>${reviews.length} published ${reviews.length===1?'story':'stories'}</p></div></section><section class="section" style="padding-top:10px"><div class="results-bar"><span>Experiences from the store’s testimonial collection</span><label>Rating <select id="review-filter" aria-label="Filter customer stories by rating"><option value="">All ratings</option><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option></select></label></div><div class="reviews-grid">${reviews.map(r=>`<article class="review-card" data-review-rating="${Math.round(Number(r.rating))}"><div class="review-stars" aria-label="${Number(r.rating)} out of 5 stars">${'★'.repeat(Math.min(5,Math.max(0,Math.round(Number(r.rating)||0))))}${'☆'.repeat(Math.max(0,5-Math.round(Number(r.rating)||0)))}</div><blockquote>“${esc(r.text)}”</blockquote><div class="review-person"><span class="review-avatar" aria-hidden="true">${esc(r.name?.trim().slice(0,1)||'H')}</span><div><strong>${esc(r.name)}</strong><small>${esc([r.role,r.location].filter(Boolean).join(' · '))}</small></div></div></article>`).join('')}</div><div id="reviews-empty" class="empty" ${reviews.length?'hidden':''}><h2>No stories for this rating.</h2><p>Choose another rating to keep exploring.</p></div></section><section class="section"><div class="info-cta"><div><h2>Have a story to share?</h2><p>Send the team your feedback or get help with your product.</p></div><a href="/contact" class="btn">Talk to Hamthel ↗</a></div></section></main>`}
const finderQuestions=[{key:'door',title:'Tell us about your door.',description:'This helps narrow the product family. The team should confirm your measurements before you buy.',choices:[['standard','Timber or metal','A standard entrance or interior door.'],['glass','Frameless glass','A glass door that needs a suitable lock.'],['rim','Rim lock or retrofit','Explore replacements and retrofit options.'],['unsure','I’m not sure yet','Start broad and ask the team for advice.']]},{key:'access',title:'How would you like to get in?',description:'Choose the access feature you care about most.',choices:[['fingerprint','Fingerprint','Unlock with a registered fingerprint.'],['pin','PIN or keypad','Use an entry code instead of a key.'],['guest','Guest access','Look for temporary codes or guest access features.'],['any','Show me the options','Compare features before deciding.']]},{key:'budget',title:'What budget feels right?',description:'We’ll use the current selling price, including the 20% discount where applicable.',choices:[['250000','Up to ₦250,000','Keep the shortlist within this budget.'],['500000','Up to ₦500,000','Explore mid-range catalogue options.'],['1000000','Up to ₦1,000,000','A wider range to compare.'],['any','No fixed budget','Show relevant products across the range.']]},{key:'use',title:'Where will it be used?',description:'One last detail to shape your shortlist.',choices:[['home','My home','Access for the household.'],['guest','Shortlet or hospitality','Consider guest access and access windows.'],['business','Office or business','Compare features for your team.'],['unsure','Still planning','Explore first, then confirm the details.']]}];
function finderMatches(answers){let products=locks().filter(p=>p.stock_status!=='Out of stock');if(answers.budget&&answers.budget!=='any')products=products.filter(p=>p.price<=Number(answers.budget));if(answers.door==='glass')products=products.filter(p=>/glass door|frameless glass/i.test(text(p)));if(answers.door==='rim')products=products.filter(p=>/\brim\b|retrofit/i.test(text(p)));if(answers.access==='fingerprint')products=products.filter(p=>/fingerprint/i.test(text(p)));if(answers.access==='pin')products=products.filter(p=>/\bpin\b|keypad/i.test(text(p)));if(answers.access==='guest'||answers.use==='guest')products=products.filter(p=>/guest|temporary|one.time|shortlet|hotel/i.test(text(p)));return products.toSorted((a,b)=>a.price-b.price)}
function quizPage(){document.title='Find your smart lock | Hamthel Smart Living';state.finder??={step:0,answers:{}};const f=state.finder,q=finderQuestions[f.step],matches=f.step===4?finderMatches(f.answers):[];return `<main class="wrap"><div class="breadcrumbs"><a href="/">Home</a> / Lock finder</div><div class="finder-header"><div><div class="eyebrow">A better starting point</div><h1>Let’s find your lock.</h1><p>Four questions. A shortlist from the current catalogue.</p></div><a class="text-link" href="/contact">Prefer to speak to someone? ↗</a></div><ol class="finder-progress" aria-label="Lock finder progress">${['Your door','Your access','Your budget','Your space'].map((label,i)=>`<li class="${i<f.step?'complete':i===f.step?'current':''}" ${i===f.step?'aria-current="step"':''}><span>${i<f.step?'✓':'0'+(i+1)}</span>${label}</li>`).join('')}</ol>${q?`<section class="finder-stage"><div class="finder-stage-copy"><span class="eyebrow">Question ${f.step+1} of 4</span><h2>${q.title}</h2><p>${q.description}</p><img src="/assets/9a80b400e38a540ad405.jpg" alt="Smart lock from the Hamthel catalogue"></div><form id="page-finder"><fieldset><legend class="sr-only">${q.title}</legend><div class="finder-choices">${q.choices.map(([value,title,body])=>`<label class="finder-choice"><input type="radio" name="answer" value="${value}" ${f.answers[q.key]===value?'checked':''} required><span><strong>${title}</strong><small>${body}</small></span></label>`).join('')}</div></fieldset><div class="finder-navigation"><button type="button" class="text-link" data-finder-back ${f.step===0?'disabled':''}>← Back</button><button class="btn" type="submit">${f.step===3?'See my matches':'Next question'} ↗</button></div></form></section>`:`<section class="section"><div class="section-top"><div><div class="eyebrow">Your starting shortlist</div><h2>${matches.length?'Meet your possibilities.':'Let’s widen the search.'}</h2><p>${matches.length?matches.length+' catalogue matches. Showing '+Math.min(6,matches.length)+' options, sorted by price.':'There are no in-stock matches for all of these preferences. Try another budget or speak to the team.'}</p></div><button class="text-link" data-finder-reset>Start again ↺</button></div><p class="finder-caveat">These are catalogue matches, not a guarantee of door compatibility. Confirm door thickness, lock dimensions and installation requirements with the Hamthel team before ordering.</p>${matches.length?`<div class="grid">${matches.slice(0,6).map(card).join('')}</div>`:'<div class="actions"><button class="btn" data-finder-reset>Adjust my answers</button><a class="btn outline" href="/contact">Ask for advice ↗</a></div>'}</section>`}</main>`}
function notFoundPage(){document.title='Page not found | Hamthel Smart Living';return `<main class="wrap section">${empty('This door doesn’t lead anywhere.','The page may have moved. Explore the marketplace or contact our team for help.')}</main>`}

function render(){const path=location.pathname;root.innerHTML=iconize(header()+(path==='/about'?aboutPage():path==='/contact'?contactPage():path==='/faq'?faqPage():path==='/reviews'?reviewsPage():path==='/quiz'?quizPage():path==='/checkout'?checkout():path==='/shop'?browse():path.startsWith('/product/')?product():path==='/saved'?saved():path==='/compare'?compare():path==='/videos'?videos():path==='/'?home():notFoundPage())+footer());const form=document.querySelector('#checkout-form');if(form&&state.checkoutDraft)for(const [name,value]of Object.entries(state.checkoutDraft)){const input=form.elements.namedItem(name);if(input)input.value=value}document.querySelectorAll('.page-nav a').forEach(a=>{if(a.getAttribute('href')===path)a.setAttribute('aria-current','page')});window.hslMarketplace={products:state.products,settings:state.settings};document.dispatchEvent(new CustomEvent('hsl:render',{detail:window.hslMarketplace}))}
function updateCounts(){document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent='('+state.cart.reduce((n,p)=>n+p.quantity,0)+')');document.querySelectorAll('[data-saved-count]').forEach(e=>e.textContent=state.saved.length);document.querySelectorAll('[data-compare-count]').forEach(e=>e.textContent='('+state.compare.length+')')}
function cart(){const form=document.querySelector('#checkout-form');if(form)state.checkoutDraft=Object.fromEntries(new FormData(form));document.querySelector('#cart-ui')?.remove();const shell=document.createElement('div');shell.id='cart-ui';shell.innerHTML=`<div class="overlay" data-close-cart></div><section class="cart-drawer" role="dialog" aria-modal="true" aria-label="Shopping bag"><div class="cart-head"><h2>Your bag (${state.cart.reduce((n,p)=>n+p.quantity,0)})</h2><button data-close-cart aria-label="Close shopping bag">×</button></div><div class="cart-items">${state.cart.length?state.cart.map(p=>`<div class="cart-item"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><h3><a href="/product/${esc(p.slug)}">${esc(p.name)}</a></h3><span class="price">${money(p.price*p.quantity)}</span><div class="quantity"><button data-cart-qty="${esc(p.id)}" data-delta="-1" aria-label="Decrease ${esc(p.name)} quantity">−</button><span>${p.quantity}</span><button data-cart-qty="${esc(p.id)}" data-delta="1" aria-label="Increase ${esc(p.name)} quantity">+</button><button class="remove" data-remove="${esc(p.id)}">Remove</button></div></div></div>`).join(''):'<p class="small-note">Your next upgrade is waiting. Add a product to get started.</p>'}</div><div class="cart-foot"><div class="total"><span>Subtotal</span><span>${money(state.cart.reduce((n,p)=>n+p.price*p.quantity,0))}</span></div><small>Delivery calculated at checkout. Final prices and availability are confirmed when you place your order. No payment is collected online.</small>${state.cart.length?'<a class="btn" href="/checkout">Continue to checkout ↗</a>':'<button class="btn" data-close-cart>Keep exploring ↗</button>'}</div></section>`;shell.innerHTML=iconize(shell.innerHTML);document.body.append(shell);root.inert=true;shell.querySelector('[aria-label="Close shopping bag"]').focus();document.body.style.overflow='hidden'}
function closeCart(){if(!document.querySelector('#cart-ui'))return;document.querySelector('#cart-ui').remove();root.inert=false;document.body.style.overflow='';if(location.pathname==='/checkout')render();document.querySelector('[data-cart]')?.focus()}
function add(id){const p=state.products.find(p=>p.id===id);if(!p||p.stock_status==='Out of stock')return;const quantity=Math.max(1,Math.min(99,Number(document.querySelector('#quantity')?.value)||1));let current=state.cart.find(x=>x.id===id);if(current)current.quantity=Math.min(99,current.quantity+quantity);else state.cart.push({id:p.id,name:p.name,price:p.price,image:image(p),slug:p.slug,brand:p.brand,quantity});persist();updateCounts();cart()}
function showVideo(id){const p=state.products.find(p=>p.id===id),d=document.querySelector('#video-dialog');if(!p||!overview(p))return;d.innerHTML=`<button class="modal-close" aria-label="Close video" data-close-video>×</button>${embedVideo(p)}<h2>${esc(p.name)}</h2><p>${p.video_url?'Product video.':'Product overview created from catalogue imagery. This is not operating or installation footage.'}</p><a class="text-link" href="/product/${esc(p.slug)}" style="display:inline-block;margin-top:15px">Explore this lock ↗</a>`;d.innerHTML=iconize(d.innerHTML);d.showModal();d.addEventListener('close',()=>{d.querySelector('video')?.pause();d.innerHTML=''}, {once:true})}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-close-cart]');if(!b)return;if(b.hasAttribute('data-cart'))cart();if(b.hasAttribute('data-download-order'))window.hslDownloadOrder(state.lastOrder);if(b.hasAttribute('data-close-cart'))closeCart();if(b.dataset.add)add(b.dataset.add);if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'Added to your shortlist':'Removed from shortlist')}if(b.dataset.video)showVideo(b.dataset.video);if(b.hasAttribute('data-close-video'))document.querySelector('#video-dialog').close();if(b.dataset.image)document.querySelector('#main-image').src=b.dataset.image;if(b.dataset.qty){const q=document.querySelector('#quantity');q.value=Math.min(99,Math.max(1,(Number(q.value)||1)+Number(b.dataset.qty)))}if(b.dataset.remove){state.cart=state.cart.filter(p=>p.id!==b.dataset.remove);persist();updateCounts();cart()}if(b.dataset.cartQty){const p=state.cart.find(p=>p.id===b.dataset.cartQty);p.quantity=Math.min(99,Math.max(1,p.quantity+Number(b.dataset.delta)));persist();updateCounts();cart()}if(b.dataset.removeCompare){state.compare=state.compare.filter(x=>x!==b.dataset.removeCompare);persist();render()}});
document.addEventListener('change',e=>{const input=e.target;if(input.hasAttribute('data-compare')){if(input.checked&&state.compare.length>=3){input.checked=false;toast('Compare up to three products. Remove one to add another.');return}state.compare=input.checked?[...new Set([...state.compare,input.dataset.compare])]:state.compare.filter(x=>x!==input.dataset.compare);persist();updateCounts();toast(input.checked?'Added to comparison — open Compare above':'Removed from comparison')}if(input.dataset.filter)location.href=url({[input.dataset.filter]:input.type==='checkbox'?(input.checked?'1':null):input.value,page:null})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCart()});
document.addEventListener('submit',async e=>{if(e.target.id!=='newsletter')return;e.preventDefault();const button=e.target.querySelector('button'),email=e.target.email.value;button.disabled=true;try{await window.hslClient.entities.Subscriber.create({email});toast('You’re on the list. Thank you!');e.target.reset()}catch(error){toast(error.message||'Unable to subscribe. Please try again.')}finally{button.disabled=false}});
async function init(){try{const [products,categories,settings,faqs,reviews]=await Promise.all([window.hslClient.entities.Product.filter({published:true},{limit:1000,sort:'sort_order'}),window.hslClient.entities.Category.filter({published:true},{limit:100,sort:'sort_order'}),window.hslClient.entities.SiteConfig.list(),location.pathname==='/faq'?window.hslClient.entities.Faq.filter({published:true},{limit:100,sort:'sort_order'}):Promise.resolve({items:[]}),location.pathname==='/reviews'?window.hslClient.entities.Testimonial.filter({published:true},{limit:100,sort:'sort_order'}):Promise.resolve({items:[]})]);state.faqs=faqs.items||faqs;state.reviews=reviews.items||reviews;state.products=products.items||products;state.categories=categories.items||categories;state.settings=settings[0]||{};state.cart=state.cart.filter(p=>state.products.some(x=>x.id===p.id)).map(p=>({...p,price:state.products.find(x=>x.id===p.id).price}));persist();render()}catch(error){root.innerHTML='<main class="wrap section"><div class="empty"><h1>We couldn’t load the marketplace.</h1><p>Please reload, or contact the Hamthel team for help.</p><button class="btn" onclick="location.reload()">Try again</button></div></main>';console.error(error)}}
init();

document.addEventListener('submit',async e=>{if(e.target.id!=='checkout-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]'),error=document.querySelector('#checkout-error');error.hidden=true;button.disabled=true;button.textContent='Placing your order…';try{const data=Object.fromEntries(new FormData(form));const order=await window.hslClient.entities.Order.create({...data,items:state.cart.map(p=>({product_id:p.id,quantity:p.quantity}))});state.lastOrder=order;state.cart=[];persist();render();scrollTo({top:0,behavior:'smooth'})}catch(err){error.textContent=err.message||'Unable to place your order. Please try again.';error.hidden=false;button.disabled=false;button.textContent='Place order';error.scrollIntoView({block:'center',behavior:'smooth'})}});

document.addEventListener('hsl:add',e=>add(e.detail.id));

document.addEventListener('input',e=>{if(e.target.id!=='faq-search')return;const query=e.target.value.trim().toLowerCase();let visible=0;document.querySelectorAll('[data-faq-text]').forEach(item=>{item.hidden=!item.dataset.faqText.includes(query);if(!item.hidden)visible++});document.querySelector('#faq-count').textContent=visible+' matching '+(visible===1?'question':'questions');document.querySelector('#faq-empty').hidden=visible>0});
document.addEventListener('change',e=>{if(e.target.id!=='review-filter')return;let count=0;document.querySelectorAll('[data-review-rating]').forEach(item=>{item.hidden=!!e.target.value&&item.dataset.reviewRating!==e.target.value;if(!item.hidden)count++});document.querySelector('#reviews-empty').hidden=count>0});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-contact-again')){document.querySelector('#contact-form').hidden=false;document.querySelector('#contact-success').hidden=true;document.querySelector('#contact-form input').focus()}if(b.hasAttribute('data-finder-back')){const selected=document.querySelector('#page-finder input:checked');if(selected)state.finder.answers[finderQuestions[state.finder.step].key]=selected.value;state.finder.step=Math.max(0,state.finder.step-1);render()}if(b.hasAttribute('data-finder-reset')){state.finder={step:0,answers:{}};render();scrollTo({top:0,behavior:'smooth'})}});
document.addEventListener('submit',async e=>{if(e.target.id==='page-finder'){e.preventDefault();const form=e.target;state.finder.answers[finderQuestions[state.finder.step].key]=new FormData(form).get('answer');state.finder.step++;render();document.querySelector('.finder-stage h2,.section-top h2')?.scrollIntoView({block:'center',behavior:'smooth'})}if(e.target.id!=='contact-form')return;e.preventDefault();const form=e.target,button=form.querySelector('button[type="submit"]'),feedback=document.querySelector('#contact-feedback'),data=Object.fromEntries(new FormData(form));if(!String(data.phone).trim()&&!String(data.email).trim()){feedback.textContent='Please add an email address or phone number so the team can reply.';feedback.hidden=false;return}button.disabled=true;button.textContent='Sending…';feedback.hidden=true;try{await window.hslClient.entities.ContactMessage.create({...data,status:'New'});form.reset();form.hidden=true;const success=document.querySelector('#contact-success');success.hidden=false;success.focus()}catch(error){feedback.textContent=error.message||'Your message could not be sent. Please try again or contact us on WhatsApp.';feedback.hidden=false}finally{button.disabled=false;button.textContent='Send enquiry'}});
